interface UserSession {
  accountId: string;
  token: string;
  expiresAt: Date;
}

export function createSession(accountId: string, token: string): UserSession {
  return {
    accountId,
    token,
    expiresAt: new Date(Date.now() + 3600000),
  };
}

export function isValidSession(session: UserSession): boolean {
  if (!session.accountId || !session.token) {
    return false;
  }
  return session.expiresAt > new Date();
}

export function getSessionKey(session: UserSession): string {
  return `session:${session.accountId}:${session.token}`;
}
